with d as (select value r from jsonb_array_elements($q$[{"notes":["Store in an airtight container for up to 5 days.","You can make this in a conventional oven at 180°C if you don't have a camp oven, bake for 18–20 minutes.","If you can't find wattleseed flour locally, use the same weight of plain flour instead, though you'll lose the earthy, distinctive flavour."],"id":"04107595-1117-44d7-b5fa-149f1076057a"},{"notes":["Make the filling ahead: it keeps in the fridge for up to 3 days. Warm it gently before stuffing.","If you don't have a tawa, use a flat non-stick frying pan or cast iron frying pan.","The dough can be made and left covered for up to 1 hour before rolling."],"id":"3b87b180-96ee-4346-851d-5eea65b11e4c"},{"notes":["Use jarred vine leaves if fresh aren't available. Rinse off the brine and pat dry.","Any whole white fish works: bream, snapper, flathead. Aim for 350–450 g per fish.","The blackened leaves are not meant to be eaten. Unwrap carefully and discard.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Light your charcoal and let it burn down to glowing coals. You want heat, not flame."},{"text":"Pat the fish dry inside and out. Season the cavity with salt, pepper and a pinch of oregano. Stuff each fish with 2 lemon slices and 1 oregano sprig."},{"text":"Lay 6 vine leaves on a work surface, overlapping them to form a base. Place a fish on top, then fold the leaves up and around it, tucking and overlapping to seal it completely. Do the same with the other fish."},{"text":"Brush each parcel lightly with olive oil. Place on the grill grate over the coals and cook until the leaves are charred and the fish flakes easily and is opaque inside."},{"text":"Cook for 10–12 minutes until the vine leaves are charred black on top. Flip the parcel carefully, then cook for another 8–10 minutes on the other side until the second side is charred and the fish is cooked through (the flesh should be opaque and flake easily at the thickest part)."},{"text":"Slide onto a plate and let rest for 2 minutes. Unwrap at the table. The leaves are burnt, but the fish inside is perfect, steamed in its own juices with lemon and herb."}],"id":"170ad0a7-4633-49bf-a3b7-365309974518"},{"notes":["The dough can be made up to 4 hours ahead and kept covered at room temperature. If you're short on time, you can stretch the noodles thinner and cook them a little faster, just watch they don't break.","You can use beef mince instead of lamb; the cumin-to-meat ratio stays the same. Some cooks add a handful of fresh coriander or a drizzle of chilli oil to finish.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"893ddd7b-43a0-4148-8452-80c07187f1d4"},{"notes":["Kokotxas are expensive and seasonal. Buy them very fresh from a good fishmonger, or ask them to order them in.","The sauce must never boil after the egg yolks are added, or it will scramble. Keep the heat low.","Don't skip the white pepper, it's gentler than black and won't speckle the delicate pale sauce.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Put the kokotxas in a wide, shallow pan with the white wine and fish stock. Bring to a gentle simmer and poach for 3 to 4 minutes, until just cooked through, they should be opaque but still delicate. Carefully transfer the kokotxas to a warm plate with a slotted spoon, keeping the cooking liquid in the pan."},{"text":"Heat the olive oil in another pan over low heat. Add the sliced garlic and cook gently, stirring, until it is just starting to soften and colour, about 2 minutes. Do not burn it."},{"text":"Pour the cooking liquid (about 300 ml) into the pan with the garlic and oil, and bring to a simmer. Add the chopped parsley and cook for 1 minute."},{"text":"In a small bowl, beat the egg yolks lightly. Remove the pan from the heat, let it cool for 30 seconds, then slowly pour in the egg yolks while whisking constantly, this makes the sauce silky and rich without scrambling the eggs. Taste and season with salt and white pepper."},{"text":"Gently return the kokotxas to the pan and warm through for 30 seconds without letting the sauce boil, until the fish is just opaque and the sauce is glossy."},{"text":"Divide among four bowls, pour the salsa verde over and around the kokotxas, and serve with crusty bread to soak up every drop."}],"id":"3cef10c2-eebc-45f4-98c7-481eef5610c0"},{"notes":["If you can't find fideuà noodles, break thin spaghetti or vermicelli into short pieces before toasting.","The socarrat is crucial, that dark, crackling crust at the bottom. Listen for it; don't walk away during those last 30 seconds.","Make the aioli ahead if you like; it keeps in the fridge for a day.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Make the aioli first: in a mortar or small bowl, pound the garlic with a pinch of salt until smooth. Add the egg yolk and stir well. Add the oil a drop at a time, whisking constantly, until it begins to emulsify. Once thickened, add the oil in a thin stream, whisking continuously. Finish with lemon juice and salt. Set aside."},{"text":"Heat the oil in a paella pan or large shallow frying pan (about 30 cm) over medium heat. Add the noodles and toast, stirring often, until they turn golden and fragrant, about 3 to 4 minutes. Remove and set aside."},{"text":"In the same pan, heat a little more oil if needed and soften the onion, garlic and capsicum over medium heat, stirring often, until soft and translucent, about 8 minutes. This sofregit should be slow and gentle, don't rush it."},{"text":"Add the tomato and cook for 2 minutes, stirring."},{"text":"Return the toasted noodles to the pan and stir to coat. Pour in the warm stock and the saffron with its soaking water. Bring to a simmer and cook without stirring for about 10 minutes, until most of the liquid has been absorbed and the noodles are tender."},{"text":"Scatter the prawns and squid over the top, season with salt and pepper, and continue cooking for about 5 minutes, stirring gently, until the prawns are cooked through (opaque and firm) and the squid is tender."},{"text":"Increase the heat to medium-high for the last minute to create the socarrat, listen for a gentle crackling sound from the bottom. Don't burn it; you want a dark, crispy crust, not black."},{"text":"Remove from heat. Scatter with fresh parsley and serve straight from the pan with the aioli on the side."}],"id":"b1c18605-427a-4da8-b908-7dea5542b995"},{"notes":["Make it no more than an hour or two before serving, the cucumbers release water over time and the salad becomes watery.","If using English cucumbers (continental), use 2 large ones and skip peeling if you prefer, the skin is thin and tender."],"id":"77d20dce-f12e-4f0a-8b4c-ba216abde01d"},{"notes":["Holds well in a low oven (150°C) for 30 minutes if dinner runs late.","Use waxy potatoes like Kipfler or baby potatoes, they hold their shape. Don't use floury potatoes.","If your anchovies are very salty, rinse and pat them dry first."],"steps":[{"text":"Heat the oven to 200°C. Butter a 2-litre baking dish."},{"text":"Layer half the potatoes into the dish, then half the onion and half the anchovies. Season lightly with salt and pepper (go easy on the salt, the anchovies are already salty). Repeat with the remaining potatoes, onion, and anchovies."},{"text":"Whisk the cream and milk together, then pour over the potato layers. Stir gently to distribute the anchovies and onions, but don't mash the potatoes. Scatter the remaining butter in small pieces on top. If you want a crust, sprinkle the panko over the butter."},{"text":"Bake for 45–50 minutes, until the potatoes are tender and the top is golden. If the top browns too fast, cover loosely with foil and uncover for the last 10 minutes to crisp up."},{"text":"Let it rest for 5 minutes, then serve warm straight from the dish."}],"id":"4f5ff4f8-0cf1-4828-b8d1-690220a83d66"},{"steps":[{"text":"Heat the oil in a large frying pan over medium-high heat. Season the trout inside and out with salt and pepper. When the oil shimmers, lay the trout in the pan and cook for 6–7 minutes without moving them, until the skin is golden and crisp."},{"text":"Carefully turn the trout and cook for another 4–5 minutes on the other side, until the flesh is just cooked through and flakes gently at the thickest part near the backbone. Transfer to a warm plate."},{"text":"Reduce the heat to medium. Add the butter to the same pan and let it melt, swirling often. After 2–3 minutes, the butter will begin to foam. Keep swirling until the milk solids turn golden and the butter smells nutty, about 1–2 minutes more."},{"text":"Add the hazelnuts to the brown butter and stir gently for 30 seconds, until the hazelnuts are golden and fragrant. Pour the hazelnut brown butter over the trout. Serve with lemon wedges and parsley scattered over, if using."}],"id":"dea859d4-025d-426d-8b60-3923e5e4253d"},{"notes":["The fish cake is essential, it's what makes this feel authentic. Find it at Asian grocers or substitute firm tofu if needed.","Make the gravy up to 4 hours ahead and reheat gently before serving; the flavours deepen. Boil the eggs separately to avoid overcooking.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Bring a small pot of water to the boil and gently lower in the eggs. Boil for 7 minutes for firm but slightly runny yolks, or 10 minutes for hard-boiled. Cool in cold water, then peel and halve."},{"text":"Heat the oil in a large pot over medium heat. Fry the shallots until golden and crispy, about 5 minutes, then add the garlic and cook for 30 seconds until fragrant."},{"text":"Add the laksa paste and fry, stirring, for 1 minute. Add the tamarind paste and stir through, then pour in the coconut milk and stock, stirring to combine."},{"text":"Add the palm sugar and turmeric, then bring to a gentle simmer. Cook for 8 to 10 minutes, stirring occasionally, until the gravy thickens slightly. Taste and season with salt and pepper."},{"text":"While the gravy simmers, bring a separate pot of salted water to the boil and cook the egg noodles according to packet directions. Drain and set aside."},{"text":"In the last minute of simmering the gravy, add the fish cake slices and bean sprouts, stirring gently."},{"text":"Divide the noodles between two bowls. Pour the gravy over each bowl, then top with the egg halves, spring onions, fried shallots and fresh chilli if you like. Serve with a lime wedge on the side."},{"text":"Squeeze the lime over just before eating, it lifts the whole thing."}],"id":"8ac6486a-9b67-48b7-85d0-3946840c77dc"},{"steps":[{"text":"Preheat the oven to 160°C. Line a 20 cm square baking tin with baking paper."},{"text":"Rub the cold butter into the flour and salt with your fingertips until the mixture resembles fine breadcrumbs. Don't overwork it."},{"text":"Stir in the caster sugar until just combined. The dough will be crumbly and hold together only loosely."},{"text":"Press the dough evenly into the prepared tin, using the back of a spoon or your fingers. It should be about 1 cm thick."},{"text":"Bake for 20–25 minutes, until pale golden and just firm to the touch. It will still feel slightly soft in the middle, that's correct."},{"text":"Remove from the oven and let cool in the tin for 5 minutes, then cut into fingers or squares while still warm. Leave to cool completely on the tin before lifting out."}],"id":"e5a606eb-4e05-4ab0-92b0-b1fa216d079c"},{"notes":["Serve with rice and peas, or white rice and a green salad.","The Scotch bonnet stays whole so you can fish it out, leave it in if you like heat, or use a milder green chilli instead.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Pat the chicken dry. Heat the oil in a large heavy-bottomed pot over medium-high heat. Working in batches, brown the chicken pieces, turning them until deeply caramelised all over, about 8–10 minutes per batch. Remove to a plate."},{"text":"Reduce the heat to medium. Add the onion and garlic to the pot, and cook, stirring, until soft and fragrant, about 3 minutes."},{"text":"Stir in the tomato paste, allspice, black pepper and salt. Cook for 1 minute, then pour in the stock and add the sugar."},{"text":"Return the chicken to the pot. Add the whole Scotch bonnet and thyme. Bring to a simmer, then reduce the heat to low, cover with a lid, and cook for 30 minutes, turning the chicken halfway through. The chicken should be cooked through (the thickest part reaching 75°C inside)."},{"text":"Taste the broth and add more salt if needed. Remove the whole Scotch bonnet before serving, it will have infused the stew with flavour without overwhelming it."}],"id":"06f71dda-0790-42e6-9dc8-cbee78967335"},{"notes":["Rice cakes keep in the freezer. No need to thaw, just separate and add straight to the boiling stock.","Swap the carrots for whatever's in the crisper: daikon, mushrooms, bok choy, even spinach all work."],"id":"99ef9cb3-7dec-49f7-b334-34fc284ae74a"},{"notes":["Make the dough the night before and refrigerate, it gives better flavour and texture.","The chole can be made up to 2 days ahead; reheat gently before serving.","Don't skip frying the bhatures to order; they're best eaten warm and puffy straight from the oil."],"id":"0f409082-c2df-433f-8c15-9424779bc121"},{"notes":["Mafé tastes better the next day as the flavours deepen. Make it ahead and reheat gently.","You can swap the pumpkin for sweet potato or potato, and the eggplant for green beans or okra.","Serve with plain white rice, or with fried plantain on the side for the kids.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"8e6b426a-8e8b-40a9-a103-f2c36bd7182b"},{"notes":["Make the pavlova base up to 2 days ahead and store in an airtight container. Assemble just before serving so the ice cream melts into the warm berries.","If you can't get hokey pokey ice cream, vanilla works fine, drizzle with toffee or caramel sauce for that honeycomb sweetness.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"a2f2d54c-8a5c-43ce-9009-9f478b6cd9af"},{"notes":["Make the rice ahead: cook it the morning of, cool it completely before mixing with the mince so the meatballs hold their shape.","Freeze unbaked meatballs on a tray, then transfer to a container. Cook from frozen, adding a few extra minutes to the simmering time.","This broth is just as good the next day, it tastes even better as the flavours settle overnight.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"In a bowl, combine the lamb mince, cooled rice, half the diced onion, half the garlic, cumin, coriander, and a pinch of salt and pepper. Mix gently until just combined, don't overwork it. Form into 12 meatballs, about the size of walnuts."},{"text":"Heat the oil in a large pot over medium heat. Working in batches, brown the meatballs on all sides, about 8 minutes total. Transfer to a plate."},{"text":"In the same pot, add the remaining onion and garlic. Cook, stirring, until softened and fragrant, about 3 minutes. Stir in the tomato paste and cook for 1 minute."},{"text":"Add the crushed tomatoes and stock. Bring to a gentle simmer until bubbling, stirring to scrape up any browned bits from the bottom of the pot."},{"text":"Return the meatballs to the pot, nestling them into the broth. Reduce heat to low, cover, and simmer for 25 minutes, until the meatballs are cooked through and the broth has thickened slightly."},{"text":"Taste and adjust seasoning with salt and pepper. Serve hot in bowls with the broth, garnished with fresh coriander if you like."}],"id":"c9d6010a-1b7e-4e39-8934-63e01aff8557"},{"notes":["If you can't find fernbrake (gosari), use the same amount of fresh spinach added at the very end, or skip it entirely.","Make ahead: simmer the beef with the stock up to step 5, then cool and refrigerate. Reheat gently and add the vegetables fresh when serving.","Use a good beef stock, homemade or from the butcher makes a real difference. Store-bought is fine, but taste it first as some are very salty.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Place the sliced beef in a large bowl and sprinkle with 1½ tsp salt. Toss to coat evenly. Let it sit for exactly 10 minutes, this draws out the juices and seasons the meat deeply."},{"text":"Add the soy sauce, gochugaru, minced garlic and sesame oil to the beef. Mix well and let sit for another 2 minutes."},{"text":"Heat a large pot or Korean stew pot (galbijjim or ttukbaegi) over medium-high heat. Add the beef mixture and stir-fry for 2 minutes until the meat begins to brown and release its juices."},{"text":"Pour in the stock and bring to a boil, about 5 minutes. Skim any foam that rises to the surface."},{"text":"Add the carrot and fernbrake (if using), and simmer for 8 minutes until the carrot is just tender."},{"text":"Add the bean sprouts and green onion, and simmer for 2 more minutes, until the sprouts are wilted but still crisp. Taste and adjust with the extra ½ tsp salt if needed, it should taste savoury and bold."},{"text":"Divide into bowls and top each with sesame seeds. Serve hot with steamed rice."}],"id":"a7245520-d411-4325-8de8-a5a355f5c37c"},{"steps":[{"text":"Wash the beetroot well, leave the skins on, and place in a large pot of cold water. Bring to a boil, then reduce heat and simmer for 25–30 minutes, until tender when pierced with a fork but still firm, this takes longer than you might think, but it matters because the inside cooks gently and stays sweet."},{"text":"While the beetroot cooks, toast the sesame seeds in a dry frying pan over medium heat, stirring constantly, for 2–3 minutes until golden and fragrant. Tip onto a plate to cool."},{"text":"Toast the walnuts in the same pan, stirring, for about 2 minutes. Set aside to cool."},{"text":"When the beetroot is tender, drain well and let it cool enough to handle, about 5 minutes. Rub off the skins under cold running water, they'll slip off easily, then cut into chunks about 2 cm across."},{"text":"In a small bowl, whisk together the pomegranate molasses, olive oil, lemon juice, minced garlic, salt and pepper."},{"text":"Place the warm beetroot in a serving bowl, pour the dressing over it, and toss gently. Let it sit for 5 minutes so the flavours meld."},{"text":"Just before serving, scatter the toasted sesame seeds and walnuts over the top, and garnish with fresh parsley if you like. The seeds stay crisp this way, you understand why when you taste them."}],"id":"e00cce32-bc0f-46d6-abea-33eaa66ca732"},{"notes":["Make the paste up to a day ahead and store in the fridge, covered. It also freezes well.","Any firm white fish works: barramundi, snapper, flathead or jewfish. Whole is best for flavour and drama, but you can use 800 g of thick fillets instead.","Don't have makrut lime leaves? Use a squeeze of fresh lime juice in the curry instead.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part. Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"steps":[{"text":"Make the curry paste: toast the coriander and cumin seeds in a dry frying pan over medium heat until fragrant, about 2 minutes, then grind in a mortar or spice grinder. Pound the red chillies, ground spices, garlic, shrimp paste, fish sauce and palm sugar together in a mortar until a rough paste forms. Add the neutral oil and stir to combine."},{"text":"Heat 2 tbsp neutral oil in a large saucepan or wok over medium-high heat. Add the curry paste and cook, stirring, until fragrant and darkened slightly, about 3 minutes."},{"text":"Pour in the coconut milk and fish stock, stirring to combine. Bring to a gentle simmer until small bubbles break the surface and the curry is lightly thickened."},{"text":"Carefully lay the whole fish into the simmering curry. The liquid should come partway up the sides of the fish. Tear in the makrut lime leaves and add the fish sauce and palm sugar."},{"text":"Simmer gently for 15–20 minutes, spooning the curry occasionally over the top of the fish, until the fish is cooked through (the flesh should flake easily and be opaque at the thickest point near the backbone)."},{"text":"Taste and adjust the seasoning with fish sauce, palm sugar or lime juice as needed. Scatter fresh Thai basil and sliced chillies over the top and serve with jasmine rice."}],"id":"d01db0ba-d677-47f5-b53e-83b99d29a7f3"},{"notes":["If you can't get rabbit, this works just as well with chicken thighs, they're tougher and hold up to long cooking like rabbit does.","Make it a day ahead; the flavours deepen overnight and it reheats beautifully.","Camp oven tip: bed the pot in hot coals and place coals on the lid for even heat, aim for about 150°C equivalent."],"steps":[{"text":"Heat the oil in a camp oven or heavy-based pot over medium-high heat. Season the rabbit pieces with salt and pepper. Brown them in batches, about 3 minutes per side, then set aside."},{"text":"Add the onions to the pot and cook, stirring, until softened and starting to colour, about 5 minutes. Add the garlic and cook for another minute."},{"text":"Return the rabbit to the pot. Pour in the red wine, scraping the bottom to lift any browned bits. Let it bubble for a minute, then add the stock, bay leaf and thyme."},{"text":"Bring to a simmer, then cover and cook low and slow, either in a camp oven over coals, a slow cooker on low for 3 hours, or a covered pot in a 150°C oven for 2 hours."},{"text":"After 1½ hours, add the carrots, potatoes and parsnip. Stir well and return to the heat."},{"text":"Continue cooking until the rabbit is tender and falling from the bone, the veg is soft, and the sauce is rich and glossy, about another hour. Taste and season with salt and pepper."},{"text":"Serve hot, straight from the pot."}],"id":"1f44fef5-977f-4253-916d-0bef601a560c"},{"notes":["Marinate overnight for best flavour, but 2 hours works in a pinch.","No grill? Use a hot cast-iron pan or oven grill, watch it so the skin chars without burning.","Serve with vinegar dipping sauce (sukang with garlic) if you've got it.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Make the marinade: warm the oil in a small bowl and cook the minced garlic for 1 minute until fragrant. Stir in the turmeric, lime juice and fish sauce. Season with salt and pepper to taste."},{"text":"Pat the chicken dry with paper towels. Place in a large bowl and pour the marinade over, turning to coat well. Cover and marinate for at least 2 hours, or overnight if you have time."},{"text":"Heat a grill or grill pan to medium-high heat until hot and sizzling when a drop of water hits it. Lightly oil the grates or pan. Remove the chicken from the marinade (reserve it), shaking off excess."},{"text":"Grill the chicken skin-side down for 6–8 minutes until golden and charred. Turn and cook the other side for another 6–8 minutes, turning occasionally and basting with reserved marinade. The chicken is done when cooked through (75°C inside) and the skin is charred and smoky."},{"text":"Rest the chicken for 3–4 minutes, then transfer to a plate. Squeeze fresh calamansi over if you like, and scatter spring onion on top. Serve hot with rice."}],"id":"6f3b6f90-b78c-4eac-bba8-094944c8711d"},{"notes":["Make ahead: prepare the fish paste up to 4 hours ahead and keep it covered in the fridge. Assemble and steam just before eating.","Can use barramundi, snapper or any firm white fish. Some cooks add egg white to make the paste lighter.","If you can't find banana leaves, use parchment paper parcels and omit the skewer, tie with kitchen string instead.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Pound or mince the fish fillet until very fine and sticky, about 3 minutes by hand or 1 minute in a food processor. Work it until it becomes almost a smooth paste."},{"text":"Mix the tamarind paste with 2 tbsp water. In a bowl, combine the fish paste with the diluted tamarind, coconut milk, palm sugar, garlic, ginger, chillies, spring onions, fish sauce and salt. Mix well with a fork or your hands until the paste is even and aromatic. Taste and adjust salt or tamarind to your liking."},{"text":"Soften the banana leaves by holding them over a gas flame for a few seconds on each side, or dip them briefly in hot water, until they are pliable. Pat dry."},{"text":"Lay one banana leaf square on a clean surface. Spoon about 2 tbsp of the fish paste into the centre. Fold the leaf into a triangle or rectangle parcel, then lay it seam-side down on your work surface. Skewer it with a wooden stick through both layers to keep it sealed. Repeat with the remaining leaves and paste, making 8 parcels."},{"text":"Bring water to a boil in a steamer or a pot with a bamboo steamer basket until steam is rising steadily. Arrange the otak-otak parcels seam-side down in a single layer in the basket, or on a steamer rack standing upright if you prefer (they hold the shape better that way)."},{"text":"Steam for 12 to 15 minutes over boiling water. The otak-otak is ready when the filling is firm and cooked through, the edges should feel set when you press gently, and the banana leaf may brown slightly at the tips."},{"text":"Remove from the steamer and let cool slightly before serving. Serve warm or at room temperature with rice or as a snack on their own."}],"id":"c4e5816e-905b-4fd6-be7d-d5b69385b4d0"},{"notes":["Make it vegetarian by leaving out the prawns and cooking the bottle gourd a few minutes longer until very tender.","Can be made ahead and reheated gently; add the prawns fresh when you reheat so they don't toughen.","Food safety: Cook prawns and other crustaceans until the shells turn pink and the flesh is opaque and firm."],"id":"fb69793a-ef70-4f29-879c-ef7427011c1c"},{"notes":["Fufu is best eaten fresh and hot. If you need to hold it, cover it loosely with foil to keep it warm but not sweating.","You can make fufu ahead and reheat it gently in the microwave with a splash of water, but the texture won't be quite as pillowy.","Green (unripe) plantains are essential, yellow or ripe ones will make it sweet."],"steps":[{"text":"Put the plantain and cassava in a large pot. Cover with cold water and add the salt. Bring to a boil, then reduce the heat and simmer for 20–25 minutes, until both are very soft and you can easily pierce them with a fork."},{"text":"Drain well in a colander, then return to the pot (or transfer to a food processor in batches if using one). Mash or process until smooth and uniform, it should be pale, creamy and hold together."},{"text":"If mashing by hand, use a wooden spoon or potato masher and work in one direction, folding the mixture over itself, until it becomes pillowy. If using a food processor, pulse until you reach a smooth, slightly sticky paste."},{"text":"Serve hot in a mound on a plate, with your favourite soup or stew on the side for dipping."}],"id":"f3e1de16-e371-4cce-9f1c-bb190c70d099"},{"notes":["Ask your fishmonger to scale and gut the flathead for you if you'd prefer. If you can't find flathead, this works beautifully with any other firm white fish of similar size, snapper, bream or barramundi all take to the same gentle treatment.","Serve with something simple: crushed new potatoes, a green salad, or just good bread to soak up the juices.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"8e10b985-9764-4e97-9011-c18f01fc083e"},{"notes":["Make the caramelised onions a day ahead and refrigerate; reheat gently with the finished soup.","Freeze the soup (without parsley garnish) for up to three months. Thaw overnight in the fridge and reheat slowly on the stove."],"id":"e651a657-d739-484a-9a2e-9f59d7e0a6e6"},{"notes":["Kanpyo keeps for months in a cool cupboard. Opened packages store best in an airtight container.","This dish is equally good served cold the next day. The flavour deepens as it sits.","If you can't find kanpyo, this method works beautifully with other dried vegetables, lotus root or burdock, both softened first."],"steps":[{"text":"Soak the kanpyo in warm water for 5 minutes until pliable. Drain and rinse gently under cold water, rubbing between your fingers to remove any dust. Cut into 8 cm lengths."},{"text":"Bring a pot of water to a boil. Add the kanpyo and simmer for 15 to 20 minutes, stirring gently now and then, until the strips are very tender and pale. Drain well."},{"text":"While the kanpyo cooks, bring the dashi to a simmer in another pot until small bubbles rise at the edges. Add the mirin, soy sauce and a pinch of salt. Taste and adjust."},{"text":"When the kanpyo is cool enough to handle, gather 4 to 5 strips together and tie loosely in a bundle using another strip of kanpyo, or a softened kombu strip. Make 6 to 8 bundles."},{"text":"Gently place the bundles into the simmering dashi. Simmer for 10 to 15 minutes, turning once halfway through, until the broth is absorbed and the kanpyo is glossy and tender."},{"text":"Transfer to a serving dish, spooning any remaining broth over the top. Serve warm or at room temperature."}],"id":"0de069fe-90ff-4621-826c-0639a01f92ea"},{"notes":["You can shape these on the skewers several hours ahead and grill just before serving.","Palm sugar gives the traditional caramel edge, but brown sugar works if you can't find it.","The paste is the soul of sate lilit, pounding it by hand rather than processing keeps the texture alive.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Pound the garlic, shallot, galangal, turmeric and chilli to a fine paste in a mortar and pestle. Add the salt."},{"text":"In a bowl, combine the pork mince, spice paste, coconut cream and palm sugar. Mix gently with your hands until just combined."},{"text":"If using lemongrass, trim each stalk to about 15 cm, keeping the white base. Wet your hands and mould about 2 tbsp of meat around the lower part of each stalk, pressing firmly so it sticks. If using skewers, press the meat firmly onto the skewer in a long shape, leaving 5 cm at the bottom clear."},{"text":"Heat a grill pan or barbecue to medium-high until hot enough to sizzle when the skewers touch it."},{"text":"Grill the sate lilit for 12–15 minutes, turning every 3 minutes, until the outside is deeply charred and the meat is cooked through (the juices should run clear)."},{"text":"Let rest for 2 minutes before serving warm with sambal and jasmine rice."}],"id":"4642fea4-3dcc-4148-835c-ef1af27c7312"},{"notes":["Dirty rice keeps well in the fridge for 3 days and reheats gently with a splash of stock if needed.","Can't find andouille? Any spicy smoked sausage will work, but andouille's got that Cajun soul.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large heavy-bottomed pot over medium-high heat. Brown the sausage until the edges caramelize, about 5 minutes. Remove and set aside."},{"text":"In the same pot, brown the chicken liver in batches until cooked through (no pink inside), about 4 minutes. Remove and set aside."},{"text":"Lower the heat to medium. Add the onion, capsicum, and celery, that's your holy trinity, and cook, stirring often, until soft and starting to colour, about 8 minutes."},{"text":"Stir in the garlic and tomato paste, cooking for 1 minute until fragrant."},{"text":"Add the rice, stirring constantly to coat in the oil, for 2 minutes."},{"text":"Pour in the stock, add the cayenne, and bring to a simmer until bubbling. Return the liver and sausage to the pot, stir, and cover."},{"text":"Cook over low heat until the rice is tender and the liquid is absorbed, about 18 minutes. Don't lift the lid."},{"text":"Season with salt and black pepper to taste. Scatter the spring onions over the top before serving."}],"id":"f1775b1f-2cd8-4f80-b14e-02069742844e"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;